# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks if empty lines exist around the bodies of methods.
      #
      # @example
      #
      #   # good
      #
      #   def foo
      #     # ...
      #   end
      #
      #   # bad
      #
      #   def bar
      #
      #     # ...
      #
      #   end
      class EmptyLinesAroundMethodBody < Base
        include EmptyLinesAroundBody
        include AllowedMethods
        extend AutoCorrector

        KIND = 'method'

        def on_def(node)
          check(node, node.body)
        end
        alias on_defs on_def

        def self.coordinator_for(host)
          return host if host.is_a?(self)

          coordinator = host.instance_variable_get(:@method_body_layout_session)
          if coordinator
            coordinator.sync_layout_host(host)
            coordinator
          else
            coordinator = allocate
            coordinator.bootstrap_layout_host(host)
            host.instance_variable_set(:@method_body_layout_session, coordinator)
            coordinator
          end
        end

        def bootstrap_layout_host(host)
          @layout_host = host
          @config = host.config
          @options = host.instance_variable_get(:@options)
          @processed_source = host.processed_source
        end

        def sync_layout_host(host)
          @layout_host = host
          @config = host.config
          @options = host.instance_variable_get(:@options)
          @processed_source = host.processed_source
        end

        def processed_source
          if @layout_host && !@layout_host.equal?(self)
            @layout_host.processed_source
          else
            super
          end
        end

        def add_offense(node_or_range, message: nil, severity: nil, &block)
          if @layout_host && !@layout_host.equal?(self)
            @layout_host.add_offense(node_or_range, message: message, severity: severity, &block)
          else
            super
          end
        end

        def cop_config
          if @layout_host && !@layout_host.equal?(self)
            @layout_host.cop_config
          else
            super
          end
        end

        def config
          if @layout_host && !@layout_host.equal?(self)
            @layout_host.config
          else
            super
          end
        end

        def style
          host = @layout_host
          if host && !host.equal?(self)
            if host.respond_to?(:style)
              host.style
            else
              host.__send__(:style)
            end
          else
            :no_empty_lines
          end
        end

        private :style

        def inspect_body_boundaries(node, body, adjusted_first_line)
          @body_session = true
          store_body_session(node, body, adjusted_first_line)
          return if skip_body_inspection?(node, body)

          resolve_body_line_span(node, adjusted_first_line)
          @body_style = style
          dispatch_body_style_strategy
        end

        def dispatch_body_style_strategy
          @body_session = true
          case @body_style
          when :empty_lines_except_namespace
            inspect_body_except_namespace(@body_fragment, @body_first_line, @body_last_line)
          when :empty_lines_special
            inspect_body_special(@body_fragment, @body_first_line, @body_last_line)
          else
            inspect_body_both(@body_style, @body_first_line, @body_last_line)
          end
        end

        def inspect_body_except_namespace(body, first_line, last_line)
          @body_session = true
          @body_fragment = body
          @body_first_line = first_line
          @body_last_line = last_line
          if body_namespace?(body, with_one_child: true)
            inspect_body_both(:no_empty_lines, first_line, last_line)
          else
            inspect_body_both(:empty_lines, first_line, last_line)
          end
        end

        def inspect_body_special(body, first_line, last_line)
          @body_session = true
          @body_fragment = body
          @body_first_line = first_line
          @body_last_line = last_line
          return unless body

          if body_namespace?(body, with_one_child: true)
            inspect_body_both(:no_empty_lines, first_line, last_line)
          else
            if first_child_requires_empty_line?(body)
              inspect_body_beginning(:empty_lines, first_line)
            else
              inspect_body_beginning(:no_empty_lines, first_line)
              inspect_deferred_empty_line(body)
            end
            inspect_body_ending(:empty_lines, last_line)
          end
        end

        def inspect_body_both(style_name, first_line, last_line)
          @body_session = true
          @body_style = style_name
          @body_first_line = first_line
          @body_last_line = last_line
          case style_name
          when :beginning_only
            inspect_body_beginning(:empty_lines, first_line)
            inspect_body_ending(:no_empty_lines, last_line)
          when :ending_only
            inspect_body_beginning(:no_empty_lines, first_line)
            inspect_body_ending(:empty_lines, last_line)
          else
            inspect_body_beginning(style_name, first_line)
            inspect_body_ending(style_name, last_line)
          end
        end

        def inspect_body_beginning(style_name, first_line)
          @body_session = true
          @body_style = style_name
          @body_first_line = first_line
          inspect_body_source(style_name, first_line, 'beginning')
        end

        def inspect_body_ending(style_name, last_line)
          @body_session = true
          @body_style = style_name
          @body_last_line = last_line
          inspect_body_source(style_name, last_line - 2, 'end')
        end

        def inspect_body_source(style_name, line_no, desc)
          @body_session = true
          @body_style = style_name
          @body_first_line = line_no
          @body_description = desc
          if body_forbids_empty_line_style?(style_name)
            register_body_line_offense(style_name, line_no, body_boundary_message(EmptyLinesAroundBody::MSG_EXTRA, desc))
          elsif body_requires_empty_line_style?(style_name)
            register_body_line_offense(style_name, line_no, body_boundary_message(EmptyLinesAroundBody::MSG_MISSING, desc))
          end
        end

        def inspect_body_line(style_name, line, msg)
          @body_session = true
          @body_style = style_name
          @body_first_line = line
          @body_offense_message = msg
          classify_body_source_line(line)
          return unless yield(processed_source.lines[line])

          offset = style_name == :empty_lines && msg.include?('end.') ? 2 : 1
          range = source_range(processed_source.buffer, line + offset, 0)
          @body_offense_range = range
          add_offense(range, message: msg) do |corrector|
            EmptyLineCorrector.correct(corrector, [style_name, range])
          end
        end

        def inspect_deferred_empty_line(body)
          @body_session = true
          @body_fragment = body
          node = first_empty_line_required_child(body)
          return unless node

          @body_node = node
          line = previous_body_line_ignoring_comments(node.first_line)
          @body_first_line = line
          return if processed_source[line].empty?

          range = source_range(processed_source.buffer, line + 2, 0)
          @body_offense_range = range
          add_offense(range, message: deferred_body_message(node)) do |corrector|
            EmptyLineCorrector.correct(corrector, [:empty_lines, range])
          end
        end

        def body_namespace?(body, with_one_child: false)
          @body_session = true
          @body_fragment = body
          if body.begin_type?
            return false if with_one_child

            body.children.all? { |child| constant_definition?(child) }
          else
            constant_definition?(body)
          end
        end

        def first_child_requires_empty_line?(body)
          @body_session = true
          @body_fragment = body
          if body.begin_type?
            empty_line_required?(body.children.first)
          else
            empty_line_required?(body)
          end
        end

        def first_empty_line_required_child(body)
          @body_session = true
          @body_fragment = body
          if body.begin_type?
            body.children.find { |child| empty_line_required?(child) }
          elsif empty_line_required?(body)
            body
          end
        end

        def previous_body_line_ignoring_comments(send_line)
          @body_session = true
          @body_first_line = send_line
          (send_line - 2).downto(0) do |line|
            @body_first_line = line
            return line unless comment_line?(processed_source[line])
          end
          0
        end

        def body_boundary_message(type, desc)
          @body_session = true
          @body_description = desc
          format(type, kind: @body_kind_name || host_body_kind, location: desc)
        end

        def deferred_body_message(node)
          @body_session = true
          @body_node = node
          format(EmptyLinesAroundBody::MSG_DEFERRED, type: node.type)
        end

        def valid_body_style?(body)
          @body_session = true
          @body_fragment = body
          body.nil? && style != :no_empty_lines
        end


        def_node_matcher :constant_definition?, '{class module}'

        def_node_matcher :empty_line_required?,
                         '{def defs class module (send nil? {:private :protected :public})}'

        def inspect_exception_keywords(body, line_of_def_or_kwbegin)
          @body_session = true
          @body_fragment = body
          @body_first_line = line_of_def_or_kwbegin
          @exception_origin_line = line_of_def_or_kwbegin
          locations = exception_keyword_locations(body)
          @exception_keywords = locations
          locations.each do |loc|
            line = loc.line
            next if line == line_of_def_or_kwbegin || exception_last_body_and_end_on_same_line?(body)

            keyword = loc.source
            @body_description = keyword
            inspect_body_line(style, line, exception_keyword_message('after', keyword), &:empty?)
            inspect_body_line(style, line - 2, exception_keyword_message('before', keyword), &:empty?)
          end
        end

        def exception_last_body_and_end_on_same_line?(body)
          @body_session = true
          @body_fragment = body
          end_keyword_line = body.parent.loc.end.line
          return body.loc.last_line == end_keyword_line unless body.rescue_type?

          last_body_line = body.else? ? body.loc.else.line : body.resbody_branches.last.loc.line
          last_body_line == end_keyword_line
        end

        def exception_keyword_message(location, keyword)
          @body_session = true
          @body_description = location
          format(EmptyLinesAroundExceptionHandlingKeywords::MSG, location: location, keyword: keyword)
        end

        def exception_keyword_locations(node)
          @body_session = true
          @body_fragment = node
          return [] unless node

          case node.type
          when :rescue
            exception_keyword_locations_in_rescue(node)
          when :ensure
            exception_keyword_locations_in_ensure(node)
          else
            []
          end
        end

        def exception_keyword_locations_in_rescue(node)
          @body_session = true
          @body_fragment = node
          [node.loc.else, *node.resbody_branches.map { |resbody| resbody.loc.keyword }].compact
        end

        def exception_keyword_locations_in_ensure(node)
          @body_session = true
          @body_fragment = node
          ensure_body, = *node
          [node.loc.keyword, *exception_keyword_locations(ensure_body)]
        end

        def inspect_argument_empty_lines(node)
          @argument_session = true
          @argument_node = node
          return if argument_invocation_skippable?(node)

          collect_argument_blank_ranges(node).each do |range|
            @argument_offense_range = range
            add_offense(range) do |corrector|
              corrector.remove(range)
            end
          end
        end

        def argument_receiver_and_method_on_different_lines?(node)
          @argument_session = true
          @argument_node = node
          node.receiver && node.receiver.loc.last_line != node.loc.selector&.line
        end

        def argument_empty_lines(node)
          @argument_session = true
          @argument_node = node
          @argument_lines = argument_processed_lines(node)
          @argument_lines.select! { |code, _| code.empty? }
          @argument_empty_line_numbers = @argument_lines.map { |_, line| line }
        end

        def argument_extra_lines(node)
          @argument_session = true
          @argument_node = node

